node --input-type=module - <<'NODE'
import assert from 'node:assert/strict';
import pg from 'pg';
import {createHash,createHmac,pbkdf2Sync,randomBytes} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import {createPgDatabase} from './dist/db/postgres.js';
assert.equal(process.env.PACKPROOF_TEST_PURPOSE,'isolated-m1-synthetic');
assert.equal(process.env.PACKPROOF_TEST_DB_HOST,'packproof-m1-20261020-db.c8v2esku2zyt.us-east-1.rds.amazonaws.com');
const secret=JSON.parse(process.env.ISOLATED_DB_SECRET);delete process.env.ISOLATED_DB_SECRET;assert.equal(secret.username,'packproof');
process.env.PACKPROOF_ENVIRONMENT='staging';process.env.PACKPROOF_DB_CA_FILE='/tmp/packproof-rds-ca.pem';
const url=new URL('postgresql://'+process.env.PACKPROOF_TEST_DB_HOST+':5432/packproof_v2?sslmode=verify-full');url.username=secret.username;url.password=secret.password;
const owner=createPgDatabase(url.href);let temporary,separate,passed=false;
try{
 const name='pp_foundation_login_'+randomBytes(8).toString('hex'),password=randomBytes(32).toString('hex'),salt=randomBytes(24),salted=pbkdf2Sync(password,salt,4096,32,'sha256');
 const stored=createHash('sha256').update(createHmac('sha256',salted).update('Client Key').digest()).digest('base64');
 const server=createHmac('sha256',salted).update('Server Key').digest('base64');
 const verifier='SCRAM-SHA-256$4096:'+salt.toString('base64')+'$'+stored+':'+server;
 await owner.db.transaction(async tx=>{
  await tx.query('CREATE ROLE '+pg.escapeIdentifier(name)+' LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 2 PASSWORD '+pg.escapeLiteral(verifier)+' VALID UNTIL '+pg.escapeLiteral(new Date(Date.now()+900000).toISOString()));
  await tx.query('GRANT packproof TO '+pg.escapeIdentifier(name)+' WITH ADMIN FALSE, INHERIT FALSE, SET TRUE');
 });
 temporary=name;url.username=name;url.password=password;url.searchParams.set('options','-c role=packproof');separate=createPgDatabase(url.href);
 const identity=(await separate.db.query('SELECT current_user AS role,session_user AS login,current_database() AS database')).rows[0];
 assert.equal(identity.role,'packproof');assert.equal(identity.login,name);assert.equal(identity.database,'packproof_v2');
 assert.equal((await separate.db.query('SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()')).rows[0].ssl,true);
 const limits=(await owner.db.query('SELECT rolinherit,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolconnlimit FROM pg_roles WHERE rolname=$1',[name])).rows[0];
 assert.equal(limits.rolconnlimit,2);delete limits.rolconnlimit;assert.ok(Object.values(limits).every(v=>v===false));passed=true;
}catch(error){console.log(JSON.stringify({event:'foundation_login_probe',status:'FAILED',sqlState:/^[0-9A-Z]{5}$/.test(error?.code??'')?error.code:undefined}));process.exitCode=1;}
finally{await separate?.close();if(temporary)await owner.db.query('DROP ROLE '+pg.escapeIdentifier(temporary));await owner.close();}
if(passed){const report={schema:'packproof.foundation-login-probe.v1',status:'PASSED',source:process.env.CANDIDATE_SHA,checks:['random_expiring_scram_login','no_implicit_owner_inheritance','explicit_owner_set_role','separate_tls_connection','temporary_role_removed'],database:'isolated-packproof_v2'};await writeFile('runtime-artifacts/login-probe.json',JSON.stringify(report));console.log(JSON.stringify(report));}

